recipes.code:
{
  "inputs": [
    {
      "id": "lithtrix-api-key",
      "type": "promptString",
      "description": "Your Lithtrix API key (ltx_...). Get one free at https://lithtrix.ai/v1/register",
      "password": true
    }
  ],
  "servers": {
    "lithtrix": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "lithtrix-mcp@0.20.2"
      ],
      "env": {
        "LITHTRIX_API_KEY": "${input:lithtrix-api-key}"
      }
    }
  }
}
